```java
import com.nano.jlayer.JLayer;
import com.nano.jlayer.audio.AudioFileFormat;
import com.nano.jlayer.audio.AudioInputStream;
import com.nano.jlayer.util.AudioUtils;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class AudioMixer {
    public static void main(String[] args) throws IOException {
        List<File> audioFiles = new ArrayList<>();
        audioFiles.add(new File("birds.wav"));
        audioFiles.add(new File("leaves.wav"));
        audioFiles.add(new File("cicadas.wav"));
        audioFiles.add(new File("children_playing.wav"));

        List<AudioInputStream> inputStreams = new ArrayList<>();
        for (File file : audioFiles) {
            inputStreams.add(AudioUtils.getAudioInputStream(file));
        }

        AudioInputStream mixedStream = AudioUtils.mix(inputStreams);
        AudioFileFormat outputFormat = AudioFileFormat.getInstance(mixedStream);
        outputFormat.write(mixedStream, new File("summer_day.wav"));
    }
}
```

