Here's an example of how you can use Google Apps Script to search for a place name in a column and store the latitude and longitude in other columns:

```javascript
function searchPlace() {
  var spreadsheet = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = spreadsheet.getActiveSheet();

  // Get the range of cells to search
  var searchRange = sheet.getRange("A1:A10"); // Assuming your place names are in column A

  // Get the range of cells to store the latitude and longitude
  var resultRange = sheet.getRange("B1:C10"); // Assuming you want to store the latitude in column B and the longitude in column C

  // Loop through each cell in the search range
  for (var i = 1; i <= searchRange.getNumRows(); i++) {
    var placeName = searchRange.getValue(i, 1);

    // Use the Google Maps API to search for the place name
    var geocoder = new google.maps.Geocoder();
    geocoder.geocode({ 'address': placeName }, function(results, status) {
      if (status == 'OK') {
        // Get the latitude and longitude of the place
        var latitude = results[0].geometry.location.lat();
        var longitude = results[0].geometry.location.lng();

        // Store the latitude and longitude in the result range
        resultRange.setValue(i, 1, latitude);
        resultRange.setValue(i, 2, longitude);
      } else {
        // Handle the error case
        console.log('Error: ' + status);
      }
    });
  }
}
```

