Here's a Go program that parses a struct in a Go source file and generates an Avro schema from it:

```go
package main

import (
	"fmt"
	"os"
	"regexp"
	"strings"

	"github.com/apache/avro/schema"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: ./parse_struct <go_source_file> <struct_name>")
		os.Exit(1)
	}

	goSourceFile := os.Args[1]
	structName := os.Args[2]

	// Parse the Go source file for the struct definition
	re := regexp.MustCompile(`type (\w+) struct {`)
	content, err := os.ReadFile(goSourceFile)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
	match := re.FindStringSubmatch(string(content))
	if match == nil {
		fmt.Println("Error: Could not find struct definition in the Go source file.")
		os.Exit(1)
	}

	// Extract the field names and types from the struct definition
	fields := []string{}
	for _, field := range strings.Split(match[0], " ") {
		field = strings.TrimSpace(field)
		if field != "" {
			fields = append(fields, field)
		}
	}

	// Generate the Avro schema
	schemaDef := &schema.Schema{
		Type:        schema.RecordType,
		Name:        structName,
		Fields:      fields,
	}

	// Save the Avro schema to a file
	schemaData, err := schema.JSON(schemaDef)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
