Here's a TypeScript program that generates a bar chart from a user-inputted dataset:

```typescript
class BarChart {
  private data: number[];

  constructor(data: number[]) {
    this.data = data;
  }

  generateChart() {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');

    canvas.width = 400;
    canvas.height = 300;

    ctx.beginPath();
    ctx.moveTo(0, this.data[0]);
    for (let i = 1; i < this.data.length; i++) {
      ctx.lineTo(i * 40, this.data[i]);
    }
    ctx.closePath();

    ctx.fillStyle = 'blue';
    ctx.fill();

    return canvas;
  }
}

const data = [10, 20, 30, 40, 50];
const chart = new BarChart(data);
const canvas = chart.generateChart();
document.body.appendChild(canvas);
```

