import React from 'react';

const RemoveWidows = ({ children }) => {
  const words = children.split(' ');
  const widowedWords = [];

  for (let i = 0; i < words.length; i++) {
    if (words[i].length > 1 && words[i - 1] !== '') {
      widowedWords.push(words[i]);
    }
  }

  return <>{widowedWords.join(' ')}</>;
};

export default RemoveWidows;
