Here's a Go function that identifies if a given sentence contains a double negative using the specified approach:

```go
package main

import (
	"fmt"
)

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	negativeWords := []string{"not", "never", "no"}

	hasDoubleNegative := isDoubleNegative(sentence, negativeWords)

	if hasDoubleNegative {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}

func isDoubleNegative(sentence string, negativeWords []string) bool {
	words := []string{}
	for _, word := range sentence {
		if word == ' ' {
			words = append(words, string(word))
		}
	}

	for _, word := range words {
		if containsNegativeWord(word, negativeWords) {
			return true
		}
	}

	return false
}

func containsNegativeWord(word string, negativeWords []string) bool {
	for _, negativeWord := range negativeWords {
		if word == negativeWord || word == "not" && containsNegativeWord(word[1:], negativeWords) {
			return true
		}
	}

	return false
}
```

