response:
To push the `portInStatus` value for each item in the `registrations` state, you can use the `map()` function in JavaScript. Here's an updated version of your code with the changes:

```javascript
import React, { useState } from 'react';
import axios from 'axios';

const api = {
  checkPortInStatus: (productCode, phoneNo) => {
    return `https://example.com/api/check_port_in_status/${productCode}/${phoneNo}`;
  },
};

function ManageRegistrationScreen() {
  const [registrations, setRegistrations] = useState([]);

  async function checkMNPStatusAPI(phoneNo, index) {
    try {
      const headers = new Headers();
      headers.append('Authorization', 'Bearer ' + user.getAccessToken());
      const response = await axios.get(api.checkPortInStatus(user.getProductCode(), phoneNo), {
        headers: headers,
      });
      setRegistrations((prevRegistrations) => {
        const updatedRegistrations = prevRegistrations.map((registration, i) => {
          if (i === index) {
            return { ...registration, portInStatus: response.data.status };
          }
          return registration;
        });
        return updatedRegistrations;
      });
    } catch (error) {
      console.error(error);
    }
  }

  // ... other code ...
}
```

In this updated version, we added an `async` function called `checkMNPStatusAPI` which uses the `map()` function to update the `portInStatus` property for each item in the `registrations` state. We also added a `setRegistrations` callback function that creates a new array with the updated `portInStatus` properties and replaces the old `registrations` state with the new one.

