# Set up variables for the domain and root folder
$domain = "your_domain"
$rootFolder = "C:\Path\To\Root\Folder"

# Define a function to check if an SID is present in the SIDHistory of any user or group in the domain
function CheckSIDInSIDHistory($sid) {
    $sidHistory = @()

    # Get all users and groups in the domain
    $users = Get-ADUser -Filter {(objectCategory -eq "person")} -Properties sIDHistory
    $groups = Get-ADGroup -Filter {(objectCategory -eq "group")} -Properties sIDHistory

    # Loop through each user and group and check if their SIDHistory contains the input SID
    foreach ($item in $users + $groups) {
        if ($item.sIDHistory -contains $sid) {
            $sidHistory += $item.sIDHistory
        }
    }

    return $sidHistory
}

# Recursively check folders for ACLs with SIDs in SIDHistory
function CheckACLsWithSIDHistory($folderPath) {
    # Get the ACL for the folder
    $acl = (Get-Acl -Path $folderPath).Access | Where-Object {$_.IdentityReference -match "\S+"}

    # Loop through each access control entry (ACE) in the ACL
    foreach ($ace in $acl) {
        # Check if the SID in the ACE is present in the SIDHistory of any user or group in the domain
        $sid = $ace.IdentityReference
        if (CheckSIDInSIDHistory($sid)) {
            Write-Host "Found an ACL with a SID in SIDHistory: $sid"
        }
    }

    # Recursively check subfolders
    if ($folderPath -contains "\") {
        Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
            CheckACLsWithSIDHistory($_.FullName)
        }
    }
}

# Call the function to check the root folder
CheckACLsWithSIDHistory($rootFolder)
```

